import{z as B,x as d,o as r,c as p,q as s,j as l,D as e,d as t,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"CDN 缓存层次与失效","description":"","frontmatter":{"title":"CDN 缓存层次与失效","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cdn-cache-hierarchy.md","filePath":"cs/cdn-cache-hierarchy.md","lastUpdated":1791413859000}'),A={name:"cs/cdn-cache-hierarchy.md"};function c(h,a,C,m,u,T){const i=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=s('<h1 id="cdn-缓存层次与失效" tabindex="-1">CDN 缓存层次与失效 <a class="header-anchor" href="#cdn-缓存层次与失效" aria-label="Permalink to &quot;CDN 缓存层次与失效&quot;">​</a></h1><div class="epigraph"><p>边缘未命中问父层，父层问源；失效用 TTL、显式 purge 或版本化 URL，否则用户看见旧表示。</p><footer>—— 据 RFC 9111 HTTP 缓存；主干 CDN 直觉课；层次缓存实践整理</footer></div><p>主干<a href="/cs/cdn-intuition">CDN 直觉</a> 已给为何近。<a href="/cs/http-semantics">HTTP 缓存头</a> 给合同。<a href="/cs/abr-streaming">上一课</a> 的分片要能命中。缺口是<strong>层次与失效</strong>：边缘–父–源、stampede、purge。本课不把边缘计算写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每个边缘都回源会打满源 \\(C\\)。层次：L1 边缘、L2 区域、源。命中率靠 TTL 与键（含 <code>Vary</code>）。失效：短 TTL、purge API、内容哈希进 URL。惊群：TTL 同时到期，要锁定或 stale-while-revalidate。Cookie 个性化几乎不可缓存。GeoDNS 把用户钉到某边缘。</p><p>不要把 CDN 写成任意计算，那是下一课。</p><p><span class="marginnote">RFC 9111。本课不点名厂商产品名当标准。</span></p><p><span class="marginnote">直觉类比：层次缓存像公司订水——工位（边缘）没水先问楼层茶水间（父层），茶水间没有才去仓库（源）整箱进货；大多数需求在楼层之间就消化了，仓库只被低频地、大批量地打扰。</span></p><h3 id="失效是一等公民" tabindex="-1">失效是一等公民 <a class="header-anchor" href="#失效是一等公民" aria-label="Permalink to &quot;失效是一等公民&quot;">​</a></h3><p>层次减源命中。Vary 与 Cookie 决定能否存。不可变 URL 最干净。惊群要用 stale-while-revalidate。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：用户 → 边缘 → 父 → 源。对照 DNS 缓存层次。与 EVPN 无关。</p><p><span class="marginnote">数字实例：边缘命中率 90%，父层再接住剩余 miss 的 90%，回源率就是 0.1×0.1=1%——两层「九成」的命中率叠起来，源只承受百分之一的流量，这就是层次的复利。</span></p>',13)),(r(),l(o,null,{default:e(()=>[n(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%22%5D%20--%3E%20E%5B%22%E8%BE%B9%E7%BC%98%22%5D%0A%20%20E%20--%3E%20P%5B%22%E7%88%B6%E7%BC%93%E5%AD%98%22%5D%0A%20%20P%20--%3E%20O%5B%22%E6%BA%90%22%5D%0A%20%20INV%5B%22purge%2F%E7%89%88%E6%9C%AC%20URL%22%5D%20--%3E%20E%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"H3 连接在边缘终止。Origin shield 减源负载。失败：某层错误缓存 200 要 purge。RPKI 管源地址，不管缓存一致性。ABR 分片不可变则永不失效，最香。",-1)),a[5]||(a[5]=E("p",null,"安全：缓存投毒若键过粗。点名。",-1)),(r(),l(o,null,{default:e(()=>[n(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E5%A4%A7%E9%87%8F%E8%BE%B9%E7%BC%98%E5%90%8C%E6%97%B6%20miss%20%E5%90%8C%E4%B8%80%20URL%22%5D%20--%3E%20LOCK%5B%22%E7%88%B6%E5%B1%82%E9%94%81%E5%AE%9A%EF%BC%9A%E5%8F%AA%E6%94%BE%E4%B8%80%E4%B8%AA%E8%AF%B7%E6%B1%82%E5%9B%9E%E6%BA%90%22%5D%0A%20%20LOCK%20--%3E%20ORIGIN%5B%22%E6%BA%90%E5%8F%AA%E6%94%B6%E5%88%B0%E4%B8%80%E6%AC%A1%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20ORIGIN%20--%3E%20FILL%5B%22%E7%BB%93%E6%9E%9C%E5%9B%9E%E5%A1%AB%E7%88%B6%E5%B1%82%E4%B8%8E%E5%90%84%E8%BE%B9%E7%BC%98%22%5D%0A%20%20SWR%5B%22stale-while-revalidate%22%5D%20--%3E%20OLD%5B%22%E5%85%88%E5%9B%9E%E6%97%A7%E5%80%BC%EF%BC%8C%E5%90%8C%E6%97%B6%E5%90%8E%E5%8F%B0%E5%88%B7%E6%96%B0%22%5D%0A%20%20NOLOCK%5B%22%E6%B2%A1%E6%9C%89%E9%94%81%E5%AE%9A%E4%B8%8E%20SWR%22%5D%20--%3E%20STAMPEDE%5B%22%E5%9B%9E%E6%BA%90%E9%A3%8E%E6%9A%B4%EF%BC%9A%E6%BA%90%E8%A2%AB%E6%89%93%E7%A9%BF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：初学者容易以为 purge 要一台一台边缘去清，实际上版本化 URL（把内容哈希写进路径）让「失效」变成「换新地址」——旧 URL 自然过期，无需任何清查动作，这也是事故时最可靠的切换方式。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ESI 的全部。边缘计算是下一课。后课默认：CDN 是分层 HTTP 缓存；失效是显式问题。</p><p>只靠很长 TTL 无版本化，事故时无法切。</p><p>下一课<a href="/cs/edge-compute">边缘计算</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>层次减少源命中。</li><li>键与 Vary 决定正确性。</li><li>失效靠 TTL、purge 或不可变 URL。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9111；CDN 实践。</li></ul>',7))])}const L=B(A,[["render",c]]);export{f as __pageData,L as default};
